"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils"; // Optional: helper for conditional classes

const navItems = [
  { name: "Home", href: "/" },
  { name: "Docs", href: "/docs" },
  { name: "Showcase", href: "/showcase" },
];

export function LandingNavbar() {
  const pathname = usePathname();

  return (
    <header className="sticky top-0 z-50 bg-white/75 backdrop-blur-md border-b border-gray-200 dark:bg-black/50 dark:border-gray-800">
      <div className="max-w-7xl mx-auto flex items-center justify-between px-6 py-4">
        {/* Logo */}
        <Link href="/" className="text-xl font-semibold tracking-tight">
          Mitra<span className="text-blue-600">AI</span>
        </Link>

        {/* Nav Links */}
        <nav className="flex space-x-6">
          {navItems.map(({ name, href }) => (
            <Link
              key={name}
              href={href}
              className={cn(
                "text-sm font-medium transition-colors hover:text-blue-600",
                pathname === href ? "text-blue-600" : "text-gray-700 dark:text-gray-300"
              )}
            >
              {name}
            </Link>
          ))}
        </nav>
      </div>
    </header>
  );
}
